  static Dictionary<Material,Material> mats=new Dictionary<Material,Material>();static Dictionary<string,Texture2D> textures=new Dictionary<string,Texture2D>();
  static List<Used> used=new List<Used>();static TerrainSurface surface;static System.Random rng=new System.Random(1804);
