  [Serializable]class Receipt{public bool passed;public int props,renderers,materials,textures,playableWidth=512;public long triangles;public Used[] sources;public TextureInfo[] textureInfo;public bool originalAssetsUntouched=true,collidersAdded=false;}
  static void Require(bool b,string e){if(!b)throw new Exception(e);}
  static T Find<T>(Scene s)where T:Component{foreach(var g in s.GetRootGameObjects()){var t=g.GetComponentInChildren<T>(true);if(t!=null)return t;}throw new Exception("Missing "+typeof(T).Name);}
